   if (cJSON_IsObject(summary))
   {
      cJSON *detached = cJSON_DetachItemViaPointer(resp, summary);
      rendered = detached ? cJSON_PrintUnformatted(detached) : NULL;
      cJSON_Delete(detached);
   }
   cJSON_Delete(resp);
